export const formatDate = (dateString) => {
    const options = { year: "numeric", month: "long", day: "numeric" }
    const date = new Date(dateString)
    const formattedDate = date.toLocaleDateString("en-US", options); // Outputs: "August 24, 2025" asse yeil yane 
  
    const hour = date.getHours()
    const minutes = date.getMinutes()
    const period = hour >= 12 ? "PM" : "AM";

    // convert 24 hr formate to 12 hr formart
    const formattedTime = `${hour % 12}:${minutes
      .toString()
      .padStart(2, "0")} ${period}` // This ensure Minute always having to digitss
  
    return `${formattedDate} | ${formattedTime}`
  }